using System;

namespace Tsumo.Tests
{
    public static class Node_modules_Tsumo_engine_src_build_bundleResources
    {
        public static Action<string, string, string, SiteOutputPlan> addBundleResources
        {
            get;
            private set;
        } = default(Action<string, string, string, SiteOutputPlan>)!;
        private static readonly System.Lazy<object?> __tsonic_module_initialization = new System.Lazy<object?>(() => __tsonic_module_init_core());
        private static object? __tsonic_module_init_core()
        {
            Node_modules_Tsumo_engine_src_resources_pageBundle.__tsonic_module_init();
            Node_modules_Tsumo_engine_src_build_outputPlan.__tsonic_module_init();
            addBundleResources = (string sourceDir, string outputPrefix, string owner, SiteOutputPlan outputPlan) =>
            {
                Tsonic.CSharp.Js.JSArray<PageBundleResourceFile> files = Node_modules_Tsumo_engine_src_resources_pageBundle.discoverPageBundleResourceFiles(sourceDir);
                for (int index = 0; index < files.length; index++)
                {
                    PageBundleResourceFile file = files[index];
                    string outputPath = outputPrefix == "" ? file.relativePath : $"{outputPrefix}/{file.relativePath}";
                    outputPlan.addAsset(outputPath, file.sourcePath, owner, "bundle");
                }
            };
            return null;
        }
        public static void __tsonic_module_init()
        {
            _ = __tsonic_module_initialization.Value;
        }
    }
}
